export const chapterBySlug = new Map(chapters.map((c) => [c.slug, c]));

export function teaser(body: string, max = 170): string {
	const first =
		body
			.split(/\n\s*\n+/)[0]
			?.replace(/\s+/g, " ")
			.trim() || "";
	if (first.length <= max) return first;
	return `${first.slice(0, max - 1).trimEnd()}…`;
}
